using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Xml;
using Meta.XR;
using UnityEditor;
using UnityEngine;
using UnityEngine.XR.OpenXR;
using UnityEngine.XR.OpenXR.Features;
namespace BWVR.Editor {
public static class FoveationChecks {
 static string DesktopSnapshot(OpenXRSettings settings){string result=EditorJsonUtility.ToJson(settings);foreach(var feature in settings.GetFeatures<OpenXRFeature>())result+=EditorJsonUtility.ToJson(feature);return result;}
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 sealed class Device:IFoveationDevice {
  public bool eligible=true,ready=true,supported=true,eyeSupported,permission,eye,acceptEye=true;public int requests,sets,level=-1,reads;public bool dynamic;
  public bool Eligible=>eligible;public bool Ready{get{reads++;return ready;}}public bool Supported{get{reads++;return supported;}}public bool EyeSupported{get{reads++;return eyeSupported;}}public bool EyePermission{get{reads++;return permission;}}public bool EyeEnabled{get{reads++;return eye;}}
  public void RequestEyePermission(){requests++;}public void SetEye(bool value){eye=value&&acceptEye;sets++;}public void SetLevel(int value,bool useDynamic){level=value;dynamic=useDynamic;sets++;}
 }
 public static void VerifyPolicy(){var p=new FoveationPolicy();var d=new Device{eligible=false};p.Tick(d);Check(p.Mode==FoveationMode.Inactive&&d.reads==0&&d.sets==0,"Desktop touched native capabilities");d.eligible=true;d.ready=false;p.Tick(d);Check(p.Mode==FoveationMode.Waiting&&d.sets==0,"Unready display was configured");d.ready=true;d.supported=false;p.Tick(d);Check(p.Mode==FoveationMode.Unsupported&&d.sets==0,"Unsupported hardware configured");d.supported=true;p.Tick(d);Check(p.Mode==FoveationMode.Fixed&&d.level==1&&d.dynamic&&d.requests==0,"No-eye fallback wrong");
  d.eyeSupported=true;p.Tick(d);p.Tick(d);Check(d.requests==1&&p.Mode==FoveationMode.Fixed,"Denied permission re-prompted or claimed eye tracking");d.permission=true;p.Tick(d);Check(d.eye&&p.Mode==FoveationMode.EyeTracked&&d.level==2,"Late permission grant ignored");p.Preference=FoveationPreference.Fixed;p.Tick(d);Check(!d.eye&&d.level==1,"Fixed mode retained gaze");p.Preference=FoveationPreference.Off;p.Tick(d);Check(!d.eye&&d.level==0&&!d.dynamic&&p.Mode==FoveationMode.Off,"Off mode retained foveation");p.Preference=FoveationPreference.Automatic;d.acceptEye=false;p.Tick(d);Check(p.Mode==FoveationMode.Fixed&&d.level==1,"Failed eye enable claimed success");d.acceptEye=true;p.Tick(d);Check(p.Mode==FoveationMode.EyeTracked,"Eye readback recovery failed");d.permission=false;p.Tick(d);Check(!d.eye&&d.requests==1&&p.Mode==FoveationMode.Fixed,"Permission revoke not respected");
  int before=d.sets;p.Suspend();Check(d.sets==before&&p.Mode==FoveationMode.Suspended,"Suspend touched native session");d.ready=false;p.Tick(d);d.ready=true;p.Tick(d);Check(d.sets>before&&p.Mode==FoveationMode.Fixed,"Resume did not reapply");before=d.sets;p.Tick(d);Check(d.sets==before,"Unchanged state rewrote native settings");Debug.Log("BWVR_FOVEATION_POLICY_PASS: desktop/no-session/unsupported; fixed fallback; permission deny/grant/revoke; eye readback; Auto/Fixed/Off; resume and bounded writes");
 }
 public static void VerifySettingsAndManifest(){
  var desktop=OpenXRSettings.GetSettingsForBuildTargetGroup(BuildTargetGroup.Standalone);string previous=DesktopSnapshot(desktop);FoveationSetup.Configure();var xr=OpenXRSettings.GetSettingsForBuildTargetGroup(BuildTargetGroup.Android);Check(xr.renderMode==OpenXRSettings.RenderMode.SinglePassInstanced&&xr.foveatedRenderingApi==OpenXRSettings.BackendFovationApi.Legacy,"Wrong Android backend");Check(xr.GetFeature<MetaXRFoveationFeature>().enabled&&xr.GetFeature<MetaXREyeTrackedFoveationFeature>().enabled&&!xr.GetFeature<FoveatedRenderingFeature>().enabled,"Wrong Android features");Check(DesktopSnapshot(desktop)==previous,"Android setup changed desktop settings");Check(OVRProjectConfig.CachedProjectConfig.eyeTrackingSupport==OVRProjectConfig.FeatureSupport.Supported,"Eye tracking became mandatory");
  Directory.CreateDirectory(".local/foveation");const string file=".local/foveation/manifest-fixture.xml";File.WriteAllText(file,"<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\" package=\"com.danoadb.bwvr\"><application><activity android:name=\"com.unity3d.player.UnityPlayerActivity\"/></application></manifest>");OVRManifestPreprocessor.PatchAndroidManifest(Path.GetFullPath(file),skipExistingAttributes:false);FoveationManifest.EnsureOptionalEyeTracking(file);FoveationManifest.EnsureOptionalEyeTracking(file);var doc=new XmlDocument();doc.Load(file);var ns=new XmlNamespaceManager(doc.NameTable);ns.AddNamespace("android","http://schemas.android.com/apk/res/android");Check(doc.SelectSingleNode("/manifest/uses-permission[@android:name='com.oculus.permission.EYE_TRACKING']",ns)!=null,"Final export omitted eye permission");var feature=doc.SelectSingleNode("/manifest/uses-feature[@android:name='oculus.software.eye_tracking']",ns);Check(feature!=null&&feature.Attributes["required","http://schemas.android.com/apk/res/android"]?.Value=="false","Eye tracking required; non-eye headset excluded");Check(doc.SelectNodes("/manifest/uses-permission[@android:name='com.oculus.permission.EYE_TRACKING']",ns).Count==1,"Duplicate permissions");Debug.Log("BWVR_FOVEATION_BUILD_SETTINGS_PASS: Android features/backend; desktop isolation; real SDK manifest permission/optional feature");
 }
 public static void VerifyDesktop(){var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var f=slice.GetComponent<QuestFoveation>();Check(f!=null&&f.Mode==FoveationMode.Inactive,"Desktop rendering was not left inactive");Check(Camera.main!=null&&UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).Count(c=>c.enabled)==1&&UnityEngine.Object.FindObjectsByType<OVRManager>(FindObjectsSortMode.None).Length==0,"Added competing XR rig/manager");Debug.Log("BWVR_FOVEATION_DESKTOP_PASS");}
 public static void VerifyMenu(Action capture=null){var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var f=slice.GetComponent<QuestFoveation>();bool had=PlayerPrefs.HasKey(QuestFoveation.PreferenceKey);int saved=PlayerPrefs.GetInt(QuestFoveation.PreferenceKey,0);var original=f.Preference;
  var panel=(GameObject)typeof(QuestSlice).GetField("panel",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(slice);try{slice.SetSanctuaryOpen(true);panel.GetComponentsInChildren<SpatialTarget>().Single(t=>t.name=="Settings").Activate();var button=panel.GetComponentsInChildren<SpatialTarget>().Single(t=>t.name=="Foveation: Auto");Check(button.gameObject.activeInHierarchy,"Rendering control is hidden");for(int i=0;i<3;i++){var before=f.Preference;button.Activate();Check(f.Preference==(FoveationPreference)(((int)before+1)%3)&&PlayerPrefs.GetInt(QuestFoveation.PreferenceKey,-1)==(int)f.Preference,"Mode control failed to persist preference");}typeof(QuestSlice).GetMethod("RefreshSanctuary",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(slice,null);capture?.Invoke();VerifyDesktop();Debug.Log("BWVR_FOVEATION_MENU_PASS: real Settings control; three modes; local preference; desktop still inactive");}
  finally{f.SetPreference(original);if(had)PlayerPrefs.SetInt(QuestFoveation.PreferenceKey,saved);else PlayerPrefs.DeleteKey(QuestFoveation.PreferenceKey);PlayerPrefs.Save();slice.SetSanctuaryOpen(false);}
 }
}
}
